// orders/OrderService.ts imports only ./ports (PaymentGateway, EmailSender, OrderRepository) and ./types

class FakePayments implements PaymentGateway {
  calls: string[] = [];
  constructor(private readonly result: ChargeResult) {}
  charge(orderId: string, learnerId: string, amountVnd: number): ChargeResult {
    this.calls.push(`${orderId} ${amountVnd}`);
    return this.result;
  }
}

test("a declined card saves a failed order and sends no receipt", () => {
  const emails = new FakeEmails();
  const orders = new InMemoryOrders();
  const service = new OrderService({
    payments: new FakePayments({ status: "declined", reason: "card_declined" }),
    emails,
    orders,
  });
  const result = service.placeOrder(an, authCourse);
  expect(result).toEqual({ ok: false, error: "payment_declined", reason: "card_declined" });
  expect(orders.saved.map((o) => o.status)).toEqual(["payment_failed"]);
  expect(emails.sent).toHaveLength(0);
});

